<?php
declare(strict_types=1);
require_once __DIR__.'/includes/api.php'; require_once __DIR__.'/includes/exam_schema.php'; $admin=require_admin_json(); ensure_exam_schema(); $action=$_GET['action']??(($_SERVER['REQUEST_METHOD']??'GET')==='GET'?'list':'save');
function exam_upload(array $file,string $prefix): ?array { if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null; if(($file['error']??1)!==UPLOAD_ERR_OK||($file['size']??0)>5*1024*1024)send_json(['ok'=>false,'message'=>'รูปแต่ละรูปต้องไม่เกิน 5MB'],422); $tmp=(string)$file['tmp_name'];$mime=(string)mime_content_type($tmp);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)send_json(['ok'=>false,'message'=>'รองรับเฉพาะ JPG PNG WEBP'],422);$dir=__DIR__.'/uploads/exams';if(!is_dir($dir))mkdir($dir,0775,true);$name=date('YmdHis').'-'.$prefix.'-'.bin2hex(random_bytes(6)).'.'.$ext;if(!move_uploaded_file($tmp,$dir.'/'.$name))send_json(['ok'=>false,'message'=>'บันทึกรูปไม่สำเร็จ'],500);return ['url'=>'uploads/exams/'.$name,'alt'=>pathinfo((string)($file['name']??''),PATHINFO_FILENAME)]; }
function exam_multi(): array {$f=$_FILES['contentImages']??null;if(!$f||!is_array($f['name']??null))return[];$idx=array_keys(array_filter($f['name'],fn($n)=>trim((string)$n)!==''));if(count($idx)>20)send_json(['ok'=>false,'message'=>'อัปโหลดได้ไม่เกิน 20 รูป'],422);$out=[];foreach($idx as $i)$out[]=exam_upload(['name'=>$f['name'][$i],'tmp_name'=>$f['tmp_name'][$i],'error'=>$f['error'][$i],'size'=>$f['size'][$i]],'content');return array_values(array_filter($out));}
function exam_images(int $id): array {$s=db()->prepare('SELECT id,image_url,alt_text FROM exam_post_images WHERE exam_post_id=:id ORDER BY sort_order,id');$s->execute(['id'=>$id]);return array_map(fn($r)=>['id'=>(string)$r['id'],'url'=>$r['image_url'],'alt'=>$r['alt_text']??''],$s->fetchAll());}
function exam_replace(int $id,array $imgs):void{db()->prepare('DELETE FROM exam_post_images WHERE exam_post_id=:id')->execute(['id'=>$id]);$s=db()->prepare('INSERT INTO exam_post_images(exam_post_id,image_url,alt_text,sort_order)VALUES(:id,:url,:alt,:sort)');foreach(array_slice($imgs,0,20)as$i=>$x)$s->execute(['id'=>$id,'url'=>$x['url'],'alt'=>$x['alt']??'','sort'=>$i*10]);}
try{if($action==='list'){$rows=db()->query('SELECT * FROM exam_posts ORDER BY updated_at DESC,id DESC')->fetchAll();send_json(['ok'=>true,'posts'=>array_map(fn($r)=>['id'=>(string)$r['id'],'type'=>$r['exam_type'],'title'=>$r['title'],'summary'=>$r['summary'],'content'=>$r['content']??'','coverImage'=>$r['cover_image']??'','status'=>$r['status'],'images'=>exam_images((int)$r['id'])],$rows)]);} $d=request_data();$id=(int)($d['id']??0);if($action==='delete'){$ns=db()->prepare('SELECT title FROM exam_posts WHERE id=:id');$ns->execute(['id'=>$id]);$target=(string)($ns->fetchColumn()?:'ตารางสอบ');db()->prepare('DELETE FROM exam_posts WHERE id=:id')->execute(['id'=>$id]);write_admin_log((int)$admin['id'],'delete_exam','exam_post',(string)$id,$target,'ลบตารางการทดสอบ '.$target);send_json(['ok'=>true,'message'=>'ลบตารางสอบแล้ว']);}$type=text_value($d,'type')==='nnet'?'nnet':'final';$title=text_value($d,'title');$summary=text_value($d,'summary');$content=nullable_text($d,'content');$status=text_value($d,'status')==='draft'?'draft':'published';if($title===''||$summary==='')send_json(['ok'=>false,'message'=>'กรุณากรอกหัวข้อและคำโปรย'],422);$cover=exam_upload($_FILES['coverImage']??[],'cover');$newImages=exam_multi();$keep=array_map('strval',(array)($d['keepImageIds']??[]));if($id){$s=db()->prepare('SELECT cover_image FROM exam_posts WHERE id=:id');$s->execute(['id'=>$id]);$old=$s->fetch();if(!$old)send_json(['ok'=>false,'message'=>'ไม่พบข้อมูล'],404);$coverUrl=$cover['url']??$old['cover_image'];$s=db()->prepare('UPDATE exam_posts SET exam_type=:type,title=:title,summary=:summary,content=:content,cover_image=:cover,status=:status,updated_by=:admin WHERE id=:id');$s->execute(['type'=>$type,'title'=>$title,'summary'=>$summary,'content'=>$content,'cover'=>$coverUrl,'status'=>$status,'admin'=>$admin['id'],'id'=>$id]);$imgs=array_values(array_filter(exam_images($id),fn($x)=>in_array($x['id'],$keep,true)));$imgs=[...$imgs,...$newImages];if(count($imgs)>20)send_json(['ok'=>false,'message'=>'เนื้อหามีรูปได้ไม่เกิน 20 รูป'],422);exam_replace($id,$imgs);write_admin_log((int)$admin['id'],'update_exam','exam_post',(string)$id,$title,'แก้ไขตารางการทดสอบ '.$title);send_json(['ok'=>true,'message'=>'แก้ไขตารางสอบแล้ว']);}$s=db()->prepare('INSERT INTO exam_posts(exam_type,title,summary,content,cover_image,status,created_by,updated_by)VALUES(:type,:title,:summary,:content,:cover,:status,:created,:updated)');$s->execute(['type'=>$type,'title'=>$title,'summary'=>$summary,'content'=>$content,'cover'=>$cover['url']??null,'status'=>$status,'created'=>$admin['id'],'updated'=>$admin['id']]);$newId=(int)db()->lastInsertId();exam_replace($newId,$newImages);write_admin_log((int)$admin['id'],'create_exam','exam_post',(string)$newId,$title,'เพิ่มตารางการทดสอบ '.$title);send_json(['ok'=>true,'message'=>'เพิ่มตารางสอบแล้ว']);}catch(Throwable $e){error_log('Exam API: '.$e->getMessage());send_json(['ok'=>false,'message'=>'บันทึกตารางสอบไม่สำเร็จ'],500);}
